  {
    "name": "rag_answer",
    "description": "适合用**知识库 / RAG 检索**回答的问题：如公司内部私有业务知识、项目文档、模型版本、标签含义、safety_rope 等业务与配置类问答；不适用于已在问题中写明 Adela 类部署平台标识（如 cuda*-trt*-*）并追问该模型在该平台上的精度、性能或 benchmark 数值的场景，此类应使用 adela_cli_eval。",
    "parameters": {
      "type": "object",
      "properties": {
        "query": {
          "type": "string",
          "description": "完全使用“用户原始输入”"
        },
        "finish_after_tool": {
          "type": "boolean",
          "description": "该工具执行完成后是否可以直接结束本轮请求。若工具结果只是中间状态、后续还要继续规划其它工具，则填 false；若该工具结果就是用户要的最终结果，则填 true。"
        }
      },
      "required": [
        "query"
      ]
    }
  },
  {
    "name": "re_question",
    "description": "在 RAG 未命中时，针对当前问题进行小步改写后继续检索。当问题含有指代（如“这个模型/它/上述方案”）或表述过短导致检索不稳定时，先调用 re_question 做实体补全与最小改写，再交给 rag_answer。示例：历史问题“安全绳检测用什么模型？”，当前问题“这个模型的精度如何？” -> 改写为“安全绳检测模型的精度如何”。",
    "parameters": {
      "type": "object",
      "properties": {
        "query": {
          "type": "string",
          "description": "待改写的原始查询（通常为用户问题或上一轮查询）。"
        },
        "rewrite_reason": {
          "type": "string",
          "description": "改写原因（如 rag_miss / coref_resolve / narrow_scope）。"
        },
        "retrieval_round": {
          "type": "integer",
          "minimum": 1,
          "maximum": 3,
          "description": "当前检索轮次（1~3）。"
        },
        "context_hint": {
          "type": "string",
          "description": "可选上下文提示，用于指代消解（例如上一问中的实体）。"
        },
        "finish_after_tool": {
          "type": "boolean",
          "description": "该工具执行完成后是否可以直接结束本轮请求。若工具结果只是中间状态、后续还要继续规划其它工具，则填 false；若该工具结果就是用户要的最终结果，则填 true。"
        }
      },
      "required": [
        "query",
        "rewrite_reason",
        "retrieval_round"
      ]
    }
  },
  {
    "name": "answerer",
    "description": "无需查阅公司内部文档的问题，比如：苹果是当季水果吗",
    "parameters": {
      "type": "object",
      "properties": {
        "mode": {
          "type": "string",
          "enum": [
            "direct",
            "rag_evidence",
            "memoryquery_trajectories"
          ],
          "description": "direct=通用知识直接回答；rag_evidence=主要依据 evidence.retrieved_chunks（可含 RAG 未命中时的弱证据）；memoryquery_trajectories=主要依据 evidence.query_trajectories。"
        },
        "finish_after_tool": {
          "type": "boolean",
          "description": "该工具执行完成后是否可以直接结束本轮请求。若工具结果只是中间状态、后续还要继续规划其它工具，则填 false；若该工具结果就是用户要的最终结果，则填 true。"
        }
      },
      "required": []
    }
  },
  {
    "name": "flux-image-generation",
    "description": "图像生成工具。可纯文本生成，也可结合参考图进行变化生成。",
    "parameters": {
      "type": "object",
      "properties": {
        "task_text": {
          "type": "string"
        },
        "source_image_required": {
          "type": "boolean"
        },
        "num_images": {
          "type": "integer",
          "minimum": 1,
          "maximum": 5
        },
        "finish_after_tool": {
          "type": "boolean",
          "description": "该工具执行完成后是否可以直接结束本轮请求。若工具结果只是中间状态、后续还要继续规划其它工具，则填 false；若该工具结果就是用户要的最终结果，则填 true。"
        }
      },
      "required": [
        "task_text",
        "source_image_required",
        "num_images"
      ]
    }
  },
  {
    "name": "qwen_detection",
    "description": "适用于检测目标的任务 Qwen。",
    "parameters": {
      "type": "object",
      "properties": {
        "label": {
          "type": "string"
        },
        "finish_after_tool": {
          "type": "boolean",
          "description": "该工具执行完成后是否可以直接结束本轮请求。若工具结果只是中间状态、后续还要继续规划其它工具，则填 false；若该工具结果就是用户要的最终结果，则填 true。"
        }
      },
      "required": [
        "label"
      ]
    }
  },
  {
    "name": "rexomni_detection",
    "description": "适用于检测目标的任务 Rex-Omni",
    "parameters": {
      "type": "object",
      "properties": {
        "label": {
          "type": "string"
        },
        "finish_after_tool": {
          "type": "boolean",
          "description": "该工具执行完成后是否可以直接结束本轮请求。若工具结果只是中间状态、后续还要继续规划其它工具，则填 false；若该工具结果就是用户要的最终结果，则填 true。"
        }
      },
      "required": [
        "label"
      ]
    }
  },
  {
    "name": "pipeline_eval",
    "description": "完整目标检测评测流水线：图片生成 - 分别使用 Qwen 和 Rex-Omni 进行标注 - 评估模型检测效果",
    "parameters": {
      "type": "object",
      "properties": {
        "task_text": {
          "type": "string"
        },
        "finish_after_tool": {
          "type": "boolean",
          "description": "该工具执行完成后是否可以直接结束本轮请求。若工具结果只是中间状态、后续还要继续规划其它工具，则填 false；若该工具结果就是用户要的最终结果，则填 true。"
        }
      },
      "required": [
        "task_text"
      ]
    }
  },
  {
    "name": "migration_advisor",
    "description": "迁移/能力边界报告助手。适用于用户询问新需求能否由现有模型或历史能力迁移、能力边界在哪里、需要补多少数据、工程/成本/风险如何，以及“不能直接支持怎么办”的问题。该工具内部会按字段检索历史资产与相似模型，并在有样例图时可执行轻量视觉探针，最后输出固定结构的迁移评估报告。不要把这类问题拆成普通 rag_answer 或 pipeline_eval；pipeline_eval 只用于用户明确要求生成样本并做目标检测评测。",
    "parameters": {
      "type": "object",
      "properties": {
        "user_query": {
          "type": "string",
          "description": "用户的原始迁移/能力边界需求，尽量完整保留。"
        },
        "use_image": {
          "type": "boolean",
          "description": "当前是否需要把上传图片作为迁移顾问的样例证据；有样例图且问题提到“这张图/样例图/图片里的目标”时填 true。"
        },
        "use_visual_probe": {
          "type": "boolean",
          "description": "是否允许迁移顾问内部对样例图运行轻量视觉探针；有图且用户要判断可行性/能力边界时通常为 true。"
        },
        "finish_after_tool": {
          "type": "boolean",
          "description": "该工具执行完成后是否可以直接结束本轮请求。若工具结果只是中间状态、后续还要继续规划其它工具，则填 false；若该工具结果就是用户要的最终结果，则填 true。"
        }
      },
      "required": [
        "user_query",
        "use_image",
        "use_visual_probe"
      ]
    }
  },
  {
    "name": "adela_cli_eval",
    "description": "用于在 Adela 上对指定模型与部署平台执行部署与 benchmark 评测。典型场景：已知或可从知识库解析的模型名/rawmodel_id，搭配具体平台串（如 cuda11.0-trt7.1-fp32-T4），询问该模型在该平台上的精度（eval_type=0）或性能（eval_type=1）。仅填 model_name 时，系统会在工具内先经 RAG 解析出 rawmodel_id，再调用 Adela CLI，不要改用 rag_answer 单独回答此类问题。",
    "parameters": {
      "type": "object",
      "properties": {
        "model_name": {
          "type": "string",
          "description": "Adela 上的模型名称。若未提供 rawmodel_id，可先提供该字段让系统通过 RAG 解析模型 ID。禁止自己编造"
        },
        "rawmodel_id": {
          "type": "integer",
          "description": "Adela 原模型 ID。"
        },
        "platform": {
          "type": "string",
          "description": "目标部署平台，例如 cuda11.0-trt7.1-int8-T4。在用户未提供该类信息的时候，禁止编造"
        },
        "eval_type": {
          "type": "integer",
          "enum": [
            0,
            1
          ],
          "description": "0=精度评测，1=性能评测。在用户未提供该类信息的时候，禁止编造"
        },
        "finish_after_tool": {
          "type": "boolean",
          "description": "该工具执行完成后是否可以直接结束本轮请求。若工具结果只是中间状态、后续还要继续规划其它工具，则填 false；若该工具结果就是用户要的最终结果，则填 true。"
        }
      },
      "required": [
        "platform",
        "eval_type"
      ]
    }
  }
]

